/**
 * Local fan-out proxy for `agent-sdk github forward`.
 *
 * `gh webhook forward` can only target a single URL, and GitHub allows just one
 * forwarder per repo/org. To feed several GitHub channels at once, we run one
 * forwarder into this loopback proxy, which re-posts each delivery — raw body
 * and signature headers intact, so per-channel `X-Hub-Signature-256` checks
 * still pass — to every channel whose declared event set matches the
 * delivery's `x-github-event`.
 */
import { createServer } from "node:http";
import { tcpAddress } from "./tcp-address.js";
import { targetLabel } from "../channels/github/forward.js";
/** Request headers copied verbatim from gh onto each fanned-out delivery. */
export const FANOUT_FORWARD_HEADERS = [
    "content-type",
    "x-github-event",
    "x-github-delivery",
    "x-github-hook-id",
    "x-hub-signature",
    "x-hub-signature-256",
    "user-agent",
    "accept",
];
/** Start a loopback proxy that fans deliveries out to {@link targets}. */
export async function startFanoutServer(targets, options = {}) {
    const server = createServer((req, res) => {
        handleFanoutRequest(req, res, targets, options);
    });
    await new Promise((resolve, reject) => {
        server.once("error", reject);
        server.listen(0, "127.0.0.1", () => {
            resolve();
        });
    });
    const address = tcpAddress(server);
    return {
        url: `http://127.0.0.1:${address.port}`,
        close: () => {
            server.close();
        },
    };
}
function handleFanoutRequest(req, res, targets, options) {
    const chunks = [];
    req.on("data", (chunk) => {
        chunks.push(chunk);
    });
    req.on("end", () => {
        void fanoutDelivery(Buffer.concat(chunks), req.headers, targets, options)
            .then((delivered) => {
            res.writeHead(200, { "content-type": "application/json" });
            res.end(JSON.stringify({ ok: true, delivered }));
        })
            .catch((error) => {
            res.writeHead(502, { "content-type": "application/json" });
            res.end(JSON.stringify({
                ok: false,
                error: error instanceof Error ? error.message : String(error),
            }));
        });
    });
}
/**
 * Re-post a single delivery to the matching targets, returning the labels that
 * accepted it. Only targets whose event set includes the delivery's
 * `x-github-event` receive it (all of them when the header is absent).
 */
export async function fanoutDelivery(body, headers, targets, options = {}) {
    const log = options.logger ?? ((line) => process.stderr.write(line));
    const event = typeof headers["x-github-event"] === "string" ? headers["x-github-event"] : undefined;
    const outbound = {};
    for (const name of FANOUT_FORWARD_HEADERS) {
        const value = headers[name];
        if (typeof value === "string") {
            outbound[name] = value;
        }
    }
    const recipients = targets.filter((target) => event === undefined || target.events.includes(event));
    // Reuse one Uint8Array view across recipients (Buffer isn't a BodyInit).
    const payload = new Uint8Array(body);
    const delivered = [];
    // Bounded by the number of GitHub channels in the project (a handful), so
    // unbounded-concurrency concerns do not apply here.
    await Promise.all(recipients.map(async (target) => {
        const label = targetLabel(target);
        try {
            const response = await fetch(target.url, {
                method: "POST",
                headers: outbound,
                body: payload,
            });
            if (!response.ok) {
                log(`[bdk] delivery to ${label} failed: HTTP ${response.status}\n`);
                return;
            }
            delivered.push(label);
        }
        catch (error) {
            log(`[bdk] delivery to ${label} failed: ${error instanceof Error ? error.message : String(error)}\n`);
        }
    }));
    if (recipients.length > 0 && delivered.length === 0) {
        throw new Error(`fan-out delivery failed for all ${recipients.length} matching channel(s)`);
    }
    return delivered;
}
